(r, big) => {
  const nd = v => ({ v, L: null, R: null });
  const put = (t, x, b) => { if (!t) return x; let c = t; for (;;) { const k = r.bool(b) ? "L" : "R"; if (!c[k]) { c[k] = x; return t; } c = c[k]; } };
  const rnd = (n, V, b) => { let t = null; for (let i = 0; i < n; i++) t = put(t, nd(V()), b); return t; };
  const mir = t => t && { v: t.v, L: mir(t.R), R: mir(t.L) };
  const ser = t => { const o = [], q = [t]; for (let i = 0; i < q.length; i++) { const x = q[i]; if (x) { o.push(x.v); q.push(x.L, x.R); } else o.push(null); } while (o.length && o[o.length - 1] === null) o.pop(); return o; };
  const nodes = t => { const o = [], s = [t]; while (s.length) { const x = s.pop(); if (x) { o.push(x); s.push(x.L, x.R); } } return o; };
  const n = big ? 4999 : r.int(0, 5), V = () => r.int(big ? -100 : 0, big ? 100 : 2);
  const half = rnd(n, V, 0.5);
  const t = { v: V(), L: half, R: mir(half) };
  if (r.bool(0.5)) {
    const all = nodes(t), x = r.pick(all);
    if (r.bool()) x.v = V();
    else if (!x.L && !x.R) x[r.bool() ? "L" : "R"] = nd(V());
  }
  return [ser(t)];
}

