function isMirrorTree(root: TreeNode | null): boolean {
  if (!root) return true;
  const q: (TreeNode | null)[] = [root.left, root.right];
  for (let i = 0; i < q.length; i += 2) {
    const a = q[i], b = q[i + 1];
    if (!a && !b) continue;
    if (!a || !b || a.val !== b.val) return false;
    q.push(a.left, b.right, a.right, b.left);
  }
  return true;
}

